<?php
namespace App\Http\Controllers;
use App\Models\{Order,OrderItem,Product}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CheckoutController extends Controller { public function create(){ $cart=session('cart',[]);abort_if(!$cart,redirect()->route('shop')->with('error','Your bag is empty.'));return view('checkout.create',['cart'=>$cart]); } public function store(Request $r){$data=$r->validate(['customer_name'=>'required|string|max:100','email'=>'nullable|email','phone'=>'required|string|max:30','address'=>'nullable|string|max:1000','notes'=>'nullable|string|max:1000']);$cart=session('cart',[]);abort_if(!$cart,redirect()->route('shop')->with('error','Your bag is empty.'));$total=0;$items=[];foreach($cart as $row){$p=Product::findOrFail($row['id']);if($p->price===null)continue;$subtotal=$p->price*$row['quantity'];$total+=$subtotal;$items[]=['product_id'=>$p->id,'product_name'=>$p->name,'unit_price'=>$p->price,'quantity'=>$row['quantity'],'subtotal'=>$subtotal];}$order=Order::create(array_merge($data,['user_id'=>auth()->id(),'order_number'=>'EH-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'total'=>$total]));$order->items()->createMany($items);session()->forget('cart');$msg="Hello Emerald Hair, I would like to confirm Order {$order->order_number}.\nCustomer: {$order->customer_name}\nPhone: {$order->phone}\nTotal: ₦".number_format($total,2);$wa='https://wa.me/'.config('emerald.whatsapp','2347069133416').'?text='.urlencode($msg);return view('checkout.success',compact('order','wa'));} }
